"""Subset only newly added fonts while retaining their existing glyph IDs."""

import io
import logging
import re
from collections import Counter

from fontTools import subset

logger = logging.getLogger(__name__)


def repair_added_font_unicode(pdf, characters_by_font_id):
    """Map emitted glyph IDs to their actual text, without changing font outlines.

    MuPDF's default cmap may choose another Unicode alias for a shared glyph
    (for example U+2011 for ASCII '-'). Only fonts added by the translator are
    passed here; original document font maps remain untouched.
    """
    by_xref = {}
    for page in pdf:
        for font in page.get_fonts(full=True):
            mappings = characters_by_font_id.get(font[4])
            if mappings:
                target = by_xref.setdefault(font[0], {})
                for gid, values in mappings.items():
                    target.setdefault(gid, Counter()).update(values)
    for xref, mappings in by_xref.items():
        entries = []
        for gid, values in sorted(mappings.items()):
            if not 0 <= gid <= 65535:
                raise ValueError("Added font glyph ID is outside the two-byte encoding")
            value = values.most_common(1)[0][0]
            entries.append(f"<{gid:04X}> <{value.encode('utf-16-be').hex().upper()}>")
        header = ["/CIDInit /ProcSet findresource begin", "12 dict begin", "begincmap",
                 "/CIDSystemInfo << /Registry (Adobe) /Ordering (UCS) /Supplement 0 >> def",
                 "/CMapName /BabelDOCActualText def", "/CMapType 2 def",
                 "1 begincodespacerange", "<0000> <FFFF>", "endcodespacerange"]
        overrides = []
        for offset in range(0, len(entries), 100):
            chunk = entries[offset:offset + 100]
            overrides.extend([f"{len(chunk)} beginbfchar", *chunk, "endbfchar"])
        kind, reference = pdf.xref_get_key(xref, "ToUnicode")
        if kind == "xref":
            cmap_xref = int(reference.split()[0])
            original = pdf.xref_stream(cmap_xref).decode("ascii")
            if "endcmap" not in original:
                raise ValueError("Added font ToUnicode is missing its endcmap marker")
            # Keep mappings for text emitted outside the intermediate document,
            # including inserted whitespace and the generator's watermark.
            content = original.replace("endcmap", "\n".join(overrides) + "\nendcmap", 1)
        else:
            cmap_xref = pdf.get_new_xref()
            pdf.update_object(cmap_xref, "<<>>")
            pdf.xref_set_key(xref, "ToUnicode", f"{cmap_xref} 0 R")
            content = "\n".join([*header, *overrides, "endcmap", "CMapName currentdict /CMap defineresource pop", "end", "end"])
        pdf.update_stream(cmap_xref, content.encode("ascii"))


def subset_added_fonts(pdf, glyphs_by_font_id):
    by_xref = {}
    for page in pdf:
        for font in page.get_fonts(full=True):
            glyphs = glyphs_by_font_id.get(font[4])
            if glyphs:
                by_xref.setdefault(font[0], set()).update(glyphs)
    for xref, glyphs in by_xref.items():
        try:
            _, _, _, data = pdf.extract_font(xref)
            options = subset.Options()
            options.retain_gids = True
            font = subset.load_font(io.BytesIO(data), options)
            subsetter = subset.Subsetter(options)
            subsetter.populate(gids=sorted(glyphs))
            subsetter.subset(font)
            target = io.BytesIO()
            subset.save_font(font, target, options)
            container = xref
            kind, descendants = pdf.xref_get_key(xref, "DescendantFonts")
            if kind == "array":
                container = int(re.search(r"\d+", descendants).group())
            kind, stream = pdf.xref_get_key(container, "FontDescriptor/FontFile2")
            if kind != "xref":
                continue
            stream_xref = int(stream.split()[0])
            compressed = target.getvalue()
            pdf.update_stream(stream_xref, compressed)
            pdf.xref_set_key(stream_xref, "Length1", str(len(compressed)))
        except Exception as exc:
            # An unrecognised font remains embedded in full; correctness wins.
            logger.warning("Keeping added font %s without subsetting: %s", xref, type(exc).__name__)
